{"content": "from typing import List

from pydantic import BaseModel, SerializeAsAny


class Channel(BaseModel):
    kind: str


class EmailChannel(Channel):
    kind: str = "email"
    address: str


class SmsChannel(Channel):
    kind: str = "sms"
    number: str


class Subscription(BaseModel):
    user: str
    # SerializeAsAny preserves v1 behavior: subclass fields (address/number)
    # are included when dumping, rather than only the base Channel fields.
    channels: List[SerializeAsAny[Channel]]


def export(sub: Subscription) -> dict:
    return sub.model_dump()
"}
